"""Second cross-reference batch: disambiguate bodies, never infer textual amendments."""
import hashlib,json,shutil
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
def sha(s):return hashlib.sha256(s.encode()).hexdigest()
def apply(c):
 d=ROOT/'documentos';data=json.loads((d/'compatibilidad_transversal_lote_02_2026.json').read_text());inv=json.loads((d/'inventario_referencias_transversales_2026.json').read_text());by={r['id']:r for r in c['records']};reviewed={r['id'] for r in c['records'] if r.get('crossHistoricalCompatibilityReview')};excluded=set();direct=set(json.loads((d/'compatibilidad_notas_historicas_2026.json').read_text())['directNoteIds']);candidate_ids={x['id'] for x in inv['candidateNotesInventory']}
 for source,h in data['sourcePDFSHA256'].items():assert c['metadata']['sources'][source]['sha256']==h
 for record in c['records']:record.pop('crossReferenceClassification',None)
 for item in data['items']:
  rid=item['id'];r=by[rid];assert rid in candidate_ids and rid not in direct and rid not in reviewed and rid not in excluded,rid
  assert sha(r['textOriginal'])==item['originalHash'] and sha(r['textEs'])==item['translationHash'],rid
  assert item['evidencePt'].lower() in r['textOriginal'].lower(),rid
  for target in item['resolvedTargets']:assert target in by,target
  assert item['requiresReformWarning'] is False
  r['crossReferenceClassification']={**item,'reviewDate':data['date'],'officialApproval':False,'externalCertification':False}
  excluded.add(rid)
 assert len(excluded)==40 and len(reviewed)==20
 pending=[x for x in inv['candidateNotesInventory'] if x['id'] not in reviewed|excluded]
 progress={**c['metadata']['crossHistoricalCompatibilityProgress'],'reviewedCandidateNotes':len(reviewed|excluded),'comparedReformRelatedNotes':len(reviewed),'excludedOtherReferenceNotes':len(excluded),'pendingCandidateNotes':len(pending),'pendingIds':[x['id'] for x in pending],'nextId':pending[0]['id'] if pending else None,'candidateReviewComplete':not pending,'globalCompatibilityReviewComplete':False,'documents':['compatibilidad_transversal_lote_01_2026_es.md','compatibilidad_transversal_lote_01_2026_pt.md','compatibilidad_transversal_lote_02_2026_es.md','compatibilidad_transversal_lote_02_2026_pt.md']}
 c['metadata']['crossHistoricalCompatibilityProgress']=progress
 for item in inv['candidateNotesInventory']:item['classificationStatus']='reviewed-reform-relation' if item['id'] in reviewed else 'resolved-other-body' if item['id'] in excluded else 'pending'
 inv.update(progress);(d/'inventario_referencias_transversales_2026.json').write_text(json.dumps(inv,ensure_ascii=False,indent=2)+'\n')
 for lang in ['es','pt']:
  es=lang=='es';parts=['# '+('Compatibilidad transversal — lote 2: identificación de referencias' if es else 'Compatibilidade transversal — lote 2: identificação das referências')+'\n\n',('> Edición de trabajo no oficial. 40 coincidencias clasificadas a partir del texto completo de las notas y su cuerpo normativo. Se resuelve el número homónimo; no se certifica vigencia general, legislación civil actual ni ausencia de relaciones implícitas.\n\n' if es else '> Edição de trabalho não oficial. 40 coincidências classificadas a partir do texto integral das notas e do respectivo diploma normativo. Resolvido o número homônimo; não se certifica vigência geral, legislação civil atual nem ausência de relações implícitas.\n\n'),'| '+('Control | Resultado' if es else 'Controle | Resultado')+' |\n| --- | --- |\n| '+('Notas rastreadas' if es else 'Notas rastreadas')+' | 816 |\n| '+('Candidatas automáticas' if es else 'Candidatas automáticas')+f" | {progress['candidateNotes']} |\n| {'Notas con relación a reformas examinada (lote 1)' if es else 'Notas com relação às alterações examinada (lote 1)'} | 20 |\n| {'Referencias a otros dispositivos identificadas (lote 2)' if es else 'Referências a outros dispositivos identificadas (lote 2)'} | 40 |\n| {'Candidatas clasificadas acumuladas' if es else 'Candidatas classificadas acumuladas'} | 60 |\n| {'Candidatas pendientes' if es else 'Candidatas pendentes'} | {len(pending)} |\n\n"]
  parts.append(('Un mismo número no identifica por sí solo el mismo artículo. Art.44 del Código Civil es distinto de CI art.44; art.27 de Liturgia o de un modelo de estatuto es distinto de CI art.27; art.8 del CD o de CI es distinto de RI-CE art.8. Las remisiones implícitas se identifican por su sección y contexto; las citas de modelos históricos no se equiparan silenciosamente a modelos actuales. Las afirmaciones civiles se atribuyen a las resoluciones históricas transcritas, sin validación jurídica actual.\n\n' if es else 'O mesmo número, por si só, não identifica o mesmo artigo. Art.44 do Código Civil é distinto de CI art.44; art.27 de Liturgia ou de um modelo de estatuto é distinto de CI art.27; art.8 do CD ou da CI é distinto de RI-CE art.8. Remissões implícitas são identificadas pela seção e contexto; citações de modelos históricos não são silenciosamente equiparadas a modelos atuais. Afirmações civis são atribuídas às resoluções históricas transcritas, sem validação jurídica atual.\n\n'))
  parts.append('SHA-256 PDF Manual 2025: `'+data['sourcePDFSHA256']['manual']+'`\n\nSHA-256 PDF Digesto 2026: `'+data['sourcePDFSHA256']['digesto']+'`\n\n')
  parts.append('| '+('Nota | Referencia identificada' if es else 'Nota | Referência identificada')+' |\n| --- | --- |\n')
  for item in data['items']:parts.append(f"| [{item['id']}](#{item['id']}) | {item['resolvedBodyEs' if es else 'resolvedBodyPt']} |\n")
  for item in data['items']:
   r=by[item['id']];parts.append(f'\n<a id="{item["id"]}"></a>\n\n## {item["id"]}\n\n'+('Referencia identificada: ' if es else 'Referência identificada: ')+item['resolvedBodyEs' if es else 'resolvedBodyPt']+'\n\n'+item['findingEs' if es else 'findingPt']+'\n\nPDF: '+', '.join(map(str,r['pages']))+'\n\n'+('Identificadores disponibles: ' if es else 'Identificadores disponíveis: ')+(', '.join(item['resolvedTargets']) or ('Referencia externa o modelo histórico; no se fuerza un identificador actual.' if es else 'Referência externa ou modelo histórico; não se força identificador atual.'))+'\n\n### '+('Nota completa' if es else 'Nota integral')+'\n\n'+r['textEs' if es else 'textOriginal']+'\n\nSHA-256 original: `'+item['originalHash']+'`\n\nSHA-256 ES: `'+item['translationHash']+'`\n\n')
  parts.append('## '+('Pendientes' if es else 'Pendências')+'\n\n'+f"{len(pending)} "+('candidatas automáticas pendientes de clasificación; no son incompatibilidades confirmadas. La aprobación editorial definitiva permanece pendiente.\n\n' if es else 'candidatas automáticas pendentes de classificação; não são incompatibilidades confirmadas. A aprovação editorial definitiva permanece pendente.\n\n')+', '.join(x['id'] for x in pending)+'\n\n'+('Siguiente lote: referencias restantes a competencias del Presbiterio, representación, comisiones y Secretaría Ejecutiva.\n' if es else 'Próximo lote: referências restantes a competências do Presbitério, representação, comissões e Secretaria Executiva.\n'))
  name=f'compatibilidad_transversal_lote_02_2026_{lang}.md';(d/name).write_text(''.join(parts));shutil.copyfile(d/name,ROOT/'static/documentos'/name)
 for name in ['compatibilidad_transversal_lote_02_2026.json','inventario_referencias_transversales_2026.json']:shutil.copyfile(d/name,ROOT/'static/documentos'/name)
 return progress
